const data = $json;
const errors = [];

function requiredString(value, field) {
  if (typeof value !== 'string' || !value.trim()) {
    errors.push(`${field} is required`);
  }
}

requiredString(data.job_id, 'job_id');
requiredString(data.claim_id, 'claim_id');
requiredString(data.policy_number, 'policy_number');
requiredString(data.claim_type, 'claim_type');
requiredString(data.incident_description, 'incident_description');

if (!Number.isInteger(data.claim_version) || data.claim_version < 1) {
  errors.push('claim_version must be a positive integer');
}

const date = data.accident_date;

if (
  typeof date !== 'string' ||
  !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
  Number.isNaN(Date.parse(date)) ||
  new Date(date).toISOString().slice(0, 10) !== date
) {
  errors.push('accident_date must be a valid YYYY-MM-DD date');
}

if (
  !data.policy_verification ||
  typeof data.policy_verification !== 'object' ||
  Array.isArray(data.policy_verification)
) {
  errors.push('policy_verification is required');
} else {
  const p = data.policy_verification;

  if (typeof p.policy_found !== 'boolean') {
    errors.push('policy_found must be boolean');
  }

  if (typeof p.source_verified !== 'boolean') {
    errors.push('source_verified must be boolean');
  }

  for (const field of ['policy_status', 'coverage_status', 'evidence_status']) {
    requiredString(p[field], `policy_verification.${field}`);
  }

  if (!Array.isArray(p.review_reasons)) {
    errors.push('review_reasons must be an array');
  }
}

if (typeof data.incident_description === 'string' &&
    data.incident_description.length > 10000) {
  errors.push('incident_description exceeds maximum length');
}

return {
  json: {
    ...data,
    input_validation: {
      valid: errors.length === 0,
      errors,
      validated_at: new Date().toISOString()
    }
  }
};

const item=$input.first().json,errors=[];let parsed;
try{const raw=item.text??item.output;parsed=typeof raw==='string'?JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')):raw}catch{errors.push('INVALID_JSON')}
const keys=['summary','observations','missing_information','supervisor_questions','requires_human_review','final_claim_decision','claim_status_changed'];
if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))errors.push('OBJECT_REQUIRED');
else {
 if(keys.some(k=>!Object.hasOwn(parsed,k))||Object.keys(parsed).some(k=>!keys.includes(k)))errors.push('INVALID_KEYS');
 if(typeof parsed.summary!=='string'||!parsed.summary.trim()||parsed.summary.length>3000)errors.push('INVALID_SUMMARY');
 if(!Array.isArray(parsed.observations)||parsed.observations.length>5)errors.push('INVALID_OBSERVATIONS');
 else for(const o of parsed.observations)if(!o||typeof o.description!=='string'||!o.description.trim()||o.description.length>2000||!['CLAIM_CLARIFICATION','VERIFICATION_GAP','REPORTED_AMOUNT_DISCREPANCY','INPUT_INTEGRITY'].includes(o.category)||!['LOW','MEDIUM','HIGH'].includes(o.severity)){errors.push('INVALID_OBSERVATION');break}
 for(const key of ['missing_information','supervisor_questions'])if(!Array.isArray(parsed[key])||parsed[key].length>5||parsed[key].some(v=>typeof v!=='string'||!v.trim()||v.length>1000))errors.push('INVALID_'+key);
 if(parsed.requires_human_review!==true||parsed.final_claim_decision!==null||parsed.claim_status_changed!==false)errors.push('INVALID_DECISION_BOUNDARY');
}
return [{json:{llm_validation:{valid:!errors.length,errors,scope:'STRUCTURE_ONLY_NOT_FACT_VERIFICATION',validated_at:new Date().toISOString()},llm_analysis:errors.length?null:parsed,provider:item.provider==='LOCAL_RULES'?'LOCAL_RULES':'LLM'}}];

const rules=$('Preliminary Analysis Engine').first().json;
const checked=$input.first().json,valid=checked.llm_validation?.valid===true,findings=[...(rules.findings??[])];
if(!valid)findings.push({code:'REPORT_FORMAT_FAILED',severity:'MEDIUM',message:'تعذر التحقق من تنسيق التقرير؛ تم الاحتفاظ بنتائج القواعد.',source:'SYSTEM'});
// The model's prose never upgrades facts/statuses. Only deterministic evidence-linked findings are authoritative here.
return [{json:{...rules,analysis_type:checked.provider==='LOCAL_RULES'?'LOCAL_RULES_AND_DOCUMENT_EVIDENCE':'RULES_WITH_UNVERIFIED_ADVISORY',
 analysis_status:valid?'COMPLETED':'REQUIRES_REVIEW',summary:rules.summary,findings,
 advisory:checked.provider==='LLM'&&valid?{text:checked.llm_analysis.summary,verification_status:'UNVERIFIED',source:'LLM'}:null,
 supervisor_questions:valid?checked.llm_analysis.supervisor_questions:[],llm_validation:checked.llm_validation,
 requires_human_review:true,final_claim_decision:null,claim_status_changed:false}}];

const intake=$('Normalize Webhook Input').first().json;if(!intake.web_integration)return [];
let analysis=null;try{analysis=$('Merge Analysis Results').first().json}catch{}
try{const saved=$('Save Preliminary Analysis').first().json.analysis_payload;if(saved&&typeof saved==='object'&&Object.keys(saved).length)analysis=saved}catch{}
const validation=$('Validate Claim Data').first().json.validation;
const result=analysis?{...analysis}:{summary:'المطالبة تحتاج تصحيح بيانات قبل التحليل.',findings:[],missing_information:validation?.completeness?.missing_fields??[],analysis_status:'REQUIRES_REVIEW'};
result.extracted=intake.claim_data;result.evidence=intake.evidence;result.field_sources=intake.field_sources??{};result.field_quality=intake.field_quality??{};result.repair_items=intake.repair_items??[];
result.flags=[...new Set([...(intake.document_flags??[]),...(validation?.completeness?.missing_fields??[]),...(validation?.warnings??[])])];
result.claim_version=intake.claim_version;result.requires_human_review=true;result.final_claim_decision=null;result.claim_status_changed=false;
return [{json:{case_id:intake.case_id,job_id:intake.job_id,result}}];
